var i=266;var a=[{id:`cooking-266-01`,theoryId:266,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What is the main purpose of recipe ratios?`,ua:`Яка основна мета співвідношень у рецептах?`},explanation:{en:`Ratios help scale composition, but equipment and process may still need adjustments.`,ua:`Співвідношення допомагають масштабувати склад, але обладнання й процес можуть вимагати коригування.`},options:[{id:`a`,text:{en:`To express ingredient relationships independently of one batch size`,ua:`Показати взаємозв’язок інгредієнтів незалежно від розміру партії`}},{id:`b`,text:{en:`To eliminate all tasting and testing`,ua:`Усунути будь-яку дегустацію та тестування`}},{id:`c`,text:{en:`To dictate a universal cooking time`,ua:`Установити універсальний час приготування`}}],answer:{optionIds:[`a`]}},{id:`cooking-266-02`,theoryId:266,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Doubling ingredient quantities always means doubling oven temperature.`,ua:`Подвоєння кількості інгредієнтів завжди означає подвоєння температури духовки.`},explanation:{en:`Batch size and heat transfer change, but oven temperature is not scaled arithmetically.`,ua:`Розмір партії та теплопередача змінюються, але температуру духовки не масштабують арифметично.`},answer:{value:!1}},{id:`cooking-266-03`,theoryId:266,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match formulation concepts with their meaning.`,ua:`Поєднайте поняття рецептури з їхніми значеннями.`},explanation:{en:`Reference bases must be clearly identified for ratios to be meaningful.`,ua:`Для змістовних співвідношень потрібно чітко визначити базу відліку.`},leftItems:[{id:`l1`,text:{en:`Ratio`,ua:`Співвідношення`}},{id:`l2`,text:{en:`Yield`,ua:`Вихід`}},{id:`l3`,text:{en:`Baker’s percentage`,ua:`Пекарський відсоток`}}],rightItems:[{id:`r2`,text:{en:`Amount of finished product`,ua:`Кількість готового продукту`}},{id:`r3`,text:{en:`Ingredient mass relative to flour mass`,ua:`Маса інгредієнта відносно маси борошна`}},{id:`r1`,text:{en:`Relative ingredient quantities`,ua:`Відносні кількості інгредієнтів`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-266-04`,theoryId:266,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A sauce recipe is being tripled, but the new pot has a much larger surface area. What should the cook do?`,ua:`Рецепт соусу збільшують утричі, але нова каструля має значно більшу площу поверхні. Що робити?`},explanation:{en:`Scaling ingredient mass does not linearly scale evaporation or heat transfer.`,ua:`Масштабування маси інгредієнтів не означає лінійного масштабування випаровування чи теплопередачі.`},options:[{id:`a`,text:{en:`Triple cooking time automatically`,ua:`Автоматично потроїти час приготування`}},{id:`b`,text:{en:`Scale ingredients, then monitor evaporation, texture and seasoning`,ua:`Масштабувати інгредієнти, а потім контролювати випаровування, текстуру та приправи`}},{id:`c`,text:{en:`Triple the burner temperature in degrees Celsius`,ua:`Потроїти температуру конфорки в градусах Цельсія`}}],answer:{optionIds:[`b`]}},{id:`cooking-266-05`,theoryId:266,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which data help define a useful recipe formula?`,ua:`Які дані потрібні для корисної рецептури?`},explanation:{en:`A formula needs quantities and target outcomes, plus process validation.`,ua:`Рецептура потребує кількостей і цільових показників, а також перевірки процесу.`},options:[{id:`a`,text:{en:`An assumption that time scales identically`,ua:`Припущення, що час масштабується так само`}},{id:`b`,text:{en:`Reference basis for percentages`,ua:`База відліку для відсотків`}},{id:`c`,text:{en:`Expected finished yield`,ua:`Очікуваний вихід готового продукту`}},{id:`d`,text:{en:`Ingredient masses`,ua:`Маси інгредієнтів`}}],answer:{optionIds:[`d`,`b`,`c`]}},{id:`cooking-266-06`,theoryId:266,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A bread formula contains 800 g flour and 560 g water. What is the hydration percentage relative to flour?`,ua:`У хлібній рецептурі є 800 г борошна та 560 г води. Яка гідратація у відсотках від маси борошна?`},explanation:{en:`560 ÷ 800 × 100 = 70%.`,ua:`Обчислення: 560 ÷ 800 × 100 = 70%.`},numericInput:{unit:`%`,unitLabel:{en:`percent`,ua:`відсотків`},allowDecimals:!1},answer:{value:70,tolerance:0,unit:`%`}}];var n={theoryId:266,exercises:a};export{n as default,a as exercises,i as theoryId};